func listenUDPTestSocket(t *testing.T) *net.UDPConn {
	t.Helper()
	conn, err := net.ListenUDP("udp4", &net.UDPAddr{IP: net.IPv4(127, 0, 0, 1)})
	if err != nil {
		t.Fatalf("listen UDP: %v", err)
	}
	t.Cleanup(func() {
		_ = conn.Close()
	})
	return conn
}

func receiveUDPObservations(conn *net.UDPConn, observations chan<- udpObservation) {
	buffer := make([]byte, 65535)
	for {
		n, from, err := conn.ReadFromUDP(buffer)
		if err != nil {
			return
		}
		observations <- udpObservation{from: from, data: bytes.Clone(buffer[:n])}
	}
}

func forwardTestRelay(
	conn *net.UDPConn,
	observations chan<- udpObservation,
	forwardErrors chan<- error,
) {
	buffer := make([]byte, 65535)
	for {
		n, from, err := conn.ReadFromUDP(buffer)
		if err != nil {
			return
		}
		packet := bytes.Clone(buffer[:n])
		observations <- udpObservation{from: from, data: packet}
		if n < anonymizedDNSHeaderSize {
			forwardErrors <- fmt.Errorf("relay received %d bytes, shorter than Anonymized DNS header", n)
			continue
		}
		target := &net.UDPAddr{
			IP:   net.IP(bytes.Clone(packet[10:26])),
			Port: int(binary.BigEndian.Uint16(packet[26:28])),
		}
		if _, err := conn.WriteToUDP(packet[anonymizedDNSHeaderSize:], target); err != nil {
			forwardErrors <- fmt.Errorf("forward relayed query: %w", err)
			return
		}
	}
}

