	config := newConfig()
	metadata, err := toml.Decode(`
server_names = ["upstream-0", "upstream-1", "upstream-2"]
lb_strategy = "round_robin"

[anonymized_dns]
skip_incompatible = true

[[anonymized_dns.routes]]
server_name = "*"
via = ["relay-0"]
`, &config)
	if err != nil {
